"""Embed reviewed Workbench fonts for offline file:// launch; no network access.

Regenerate from the repository root: python3 atlas/build_workbench_fonts.py
"""

from __future__ import annotations

import base64
from pathlib import Path

FONT_ROOT = Path(__file__).resolve().parent / "atlas-plugin" / "workbench" / "fonts"


def build() -> Path:
    """Write deterministic CSS from the three bundled Open Sans font files."""
    rules = [
        "/* Generated by python3 atlas/build_workbench_fonts.py.\n"
        "   Sources: bundled Open Sans WOFF2 files; license: OFL.txt.\n"
        "   Data URLs keep font loading self-contained for offline file:// launch. */\n"
    ]
    for name, family, weight in (
        ("OpenSans-Regular.woff2", "Atlas Open Sans", 400),
        ("OpenSans-SemiBold.woff2", "Atlas Open Sans", 600),
        ("OpenSans_Condensed-Bold.woff2", "Atlas Open Sans Condensed", 700),
    ):
        encoded = base64.b64encode((FONT_ROOT / name).read_bytes()).decode("ascii")
        rules.append(
            "@font-face {\n"
            f'  font-family: "{family}";\n'
            f'  src: url("data:font/woff2;base64,{encoded}") format("woff2");\n'
            "  font-style: normal;\n"
            f"  font-weight: {weight};\n"
            "  font-display: swap;\n"
            "}\n"
        )
    output = FONT_ROOT / "fonts.css"
    output.write_text("\n".join(rules), encoding="utf-8", newline="\n")
    return output


if __name__ == "__main__":
    build()
